7	<meta name="description" content="海餅乾俱樂部・商務健身房——戰略地圖公開，不藏一字。台南最優質的商務團隊由大樹教練主理。付了會費只是買到進門的權利，真正的商業肌肉，靠當責訓練長出來。100 位企業家、年產值 5 億的訓練中心。26 年培訓、6,000+ 場演講、足跡四國。">
8	<meta property="og:title" content="海餅乾俱樂部・商務健身房｜大樹教練主理">
9	<meta property="og:description" content="付了會費，只是買到進門的權利。真正的商業肌肉，靠當責訓練長出來。">
10	<meta property="og:type" content="website">
11	<link rel="preconnect" href="https://fonts.googleapis.com">
12	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
13	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&family=Noto+Serif+TC:wght@700;900&display=swap" rel="stylesheet">
14	<link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet">
15	<style>
16	:root{
17	  --ink:#1c2a28;
18	  --ink-soft:#4b5b58;
19	  --ink-faint:#7a8a87;
20	  --paper:#faf6ee;
21	  --paper-2:#f1e9d8;
22	  --paper-3:#fffef7;
23	  --deep:#163b35;
24	  --deep-2:#0f2a26;
25	  --deep-3:#1f4a43;
26	  --teal-soft:#b9d6c8;
27	  --accent:#e07a3c;
28	  --accent-2:#c25e22;
29	  --accent-soft:#fcd2b5;
30	  --gold:#b58a4f;
31	  --line-green:#06c755;
32	  --line-soft:rgba(28,42,40,.12);
33	  --line-mid:rgba(28,42,40,.22);
34	  --red-soft:#c45252;
35	  --green-good:#3d8a5a;
36	}
37	*{box-sizing:border-box}
38	html{scroll-behavior:smooth}
39	html,body{margin:0;padding:0;background:var(--paper);font-family:"Noto Sans TC",system-ui,-apple-system,sans-serif;color:var(--ink);-webkit-font-smoothing:antialiased;line-height:1.7}
40	img{max-width:100%;display:block}
41	a{color:inherit;text-decoration:none}
42	section{padding:80px 24px}
43	.wrap{max-width:1100px;margin:0 auto}
44	.serif{font-family:"Noto Serif TC",serif;font-weight:900}
45	.eyebrow{display:inline-block;font-size:12px;letter-spacing:.32em;font-weight:800;color:var(--accent-2);margin-bottom:14px}
46	.sec-title{font-family:"Noto Serif TC",serif;font-weight:900;font-size:42px;line-height:1.3;color:var(--deep-2);margin:0 0 18px;letter-spacing:.02em}
47	.sec-title-underline{width:64px;height:4px;background:linear-gradient(90deg,var(--accent),var(--accent-2));border-radius:2px;margin-bottom:28px}
48	.sec-lead{font-size:17px;color:var(--ink-soft);max-width:680px;margin:0 0 36px;line-height:1.85}
49	
50	/* ===== NAV ===== */
51	.nav{
52	  position:sticky;top:0;z-index:50;
53	  background:rgba(250,246,238,.92);
54	  backdrop-filter:blur(14px);
55	  border-bottom:1px solid var(--line-soft);
56	}
57	.nav-inner{
58	  max-width:1200px;margin:0 auto;
59	  display:flex;justify-content:space-between;align-items:center;
60	  padding:14px 24px;gap:24px;
61	}
62	.nav-logo{display:flex;align-items:center;gap:12px}
63	.nav-logo .badge{
64	  width:46px;height:46px;border-radius:12px;
65	  background:linear-gradient(135deg,var(--deep),var(--deep-2));
66	  color:var(--accent-soft);display:grid;place-items:center;font-size:22px;
67	}
68	.nav-logo .text .name{font-family:"Noto Serif TC",serif;font-weight:900;font-size:18px;letter-spacing:.02em;color:var(--deep-2);line-height:1.1}
69	.nav-logo .text .sub{font-size:10.5px;color:var(--accent-2);letter-spacing:.22em;font-weight:800;margin-top:3px}
70	.nav-links{display:flex;gap:28px;font-size:14px;font-weight:600;color:var(--ink-soft)}
71	.nav-links a:hover{color:var(--accent-2)}
72	.nav-cta{display:flex;gap:10px;align-items:center}
73	.btn-line-nav{
74	  display:inline-flex;align-items:center;gap:6px;
75	  padding:9px 16px;border-radius:999px;
76	  background:#fff;border:1px solid var(--line-soft);
77	  font-size:13px;font-weight:700;color:var(--ink);
78	}
79	.btn-line-nav i{color:var(--line-green)}
80	.btn-primary{
81	  display:inline-flex;align-items:center;gap:8px;
82	  padding:11px 20px;border-radius:999px;
83	  background:linear-gradient(135deg,var(--accent),var(--accent-2));
84	  color:#fff;font-size:13.5px;font-weight:900;letter-spacing:.04em;
85	  border:0;cursor:pointer;font-family:inherit;
86	  box-shadow:0 10px 22px -10px rgba(224,122,60,.6);
87	  transition:.22s;
88	}
89	.btn-primary:hover{transform:translateY(-2px);box-shadow:0 14px 30px -10px rgba(224,122,60,.75)}
90	@media (max-width:880px){
91	  .nav-links{display:none}
92	  .btn-line-nav span{display:none}
93	}
94	
95	/* ===== HERO ===== */
96	.hero{
97	  background:
98	    radial-gradient(700px 380px at 90% -10%, rgba(224,122,60,.18), transparent 60%),
99	    radial-gradient(600px 320px at -10% 110%, rgba(22,59,53,.15), transparent 60%),
100	    var(--paper);
101	  padding:80px 24px 90px;
102	}
103	.hero-grid{
104	  max-width:1180px;margin:0 auto;
105	  display:grid;grid-template-columns:1.25fr 1fr;gap:60px;align-items:center;
106	}
107	.hero-eyebrow{
108	  display:inline-flex;align-items:center;gap:10px;
109	  padding:7px 16px;border-radius:999px;
110	  background:#fff;border:1.5px solid var(--accent-soft);
111	  font-size:12.5px;font-weight:800;color:var(--accent-2);letter-spacing:.18em;
112	  margin-bottom:24px;
113	}
114	.hero-eyebrow .dot{width:8px;height:8px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px rgba(224,122,60,.18)}
115	.hero h1{
116	  font-family:"Noto Serif TC",serif;font-weight:900;
117	  font-size:64px;line-height:1.15;letter-spacing:.02em;
118	  color:var(--deep-2);margin:0 0 18px;
119	}
120	.hero h1 em{
